import re, glob
txt = {}
for f in sorted(glob.glob('draft/*.md')) + sorted(glob.glob('figures/*.md')):
    txt[f] = open(f).read()
bad = ['—', '–', 'TODO', 'TBD', 'XXX', 'placeholder', 'draftsperson', '?', 'e.g.', 'i.e.']
for f, t in txt.items():
    for b in bad:
        if b in t:
            print('MARKER', f, repr(b))
for f in sorted(glob.glob('figures/*.md')):
    print(f, 'chars', len(txt[f]))
tab = re.findall(r'\|\s*(\d{3})\s*\|\s*([^|]+?)\s*\|', txt['draft/numerals.md'])
print('table count', len(tab))
names = [n for _, n in tab]
print('dup names', [n for n in names if names.count(n) > 1])
body = ''.join(v for k, v in txt.items() if k.startswith('draft/') and 'numerals' not in k)
used = set(re.findall(r'\b(\d{3})\b', body))
print('in body not table', sorted(used - {n for n, _ in tab}))
print('in table not body', sorted({n for n, _ in tab} - used))
figs = ''.join(v for k, v in txt.items() if k.startswith('figures/'))
figused = set(re.findall(r'\b(\d{3})\b', figs))
print('fig numerals not in table', sorted(figused - {n for n, _ in tab}))
print('table numerals on no figure', sorted({n for n, _ in tab} - figused))
for f in sorted(glob.glob('figures/*.md')):
    ns = re.findall(r'^- (\d{3}) ([^:]+):', txt[f], re.M)
    print(f, len(ns), [n for n, _ in ns])
    for n, nm in ns:
        canon = dict(tab)[n]
        if nm.strip() != canon:
            print('  NAME MISMATCH', n, nm, '!=', canon)
